 99		if err != nil {
100			return err
101		}
102		// if the jsonBytes is array values
103		if bytes.HasPrefix(jsonBytes, bytesconv.StringToBytes("[")) && bytes.HasSuffix(jsonBytes,
104			bytesconv.StringToBytes("]")) {
