119	func (r JsonpJSON) Render(w http.ResponseWriter) (err error) {
120		r.WriteContentType(w)
121		ret, err := json.Marshal(r.Data)
122		if err != nil {
123			return err
124		}
125	
126		if r.Callback == "" {
127			_, err = w.Write(ret)
128			return err
129		}
130	
131		callback := template.JSEscapeString(r.Callback)
132		if _, err = w.Write(bytesconv.StringToBytes(callback)); err != nil {
133			return err
134		}
135	
136		if _, err = w.Write(bytesconv.StringToBytes("(")); err != nil {
137			return err
138		}
139	
140		if _, err = w.Write(ret); err != nil {
141			return err
142		}
143	
144		if _, err = w.Write(bytesconv.StringToBytes(");")); err != nil {
145			return err
146		}
147	
148		return nil
149	}
