183	func (r PureJSON) Render(w http.ResponseWriter) error {
184		r.WriteContentType(w)
185		encoder := json.NewEncoder(w)
186		encoder.SetEscapeHTML(false)
187		return encoder.Encode(r.Data)
188	}
