    43	// RecoveryWithWriter returns a middleware for a given writer that recovers from any panics and writes a 500 if there was one.
    44	func RecoveryWithWriter(out io.Writer, recovery ...RecoveryFunc) HandlerFunc {
    45		if len(recovery) > 0 {
