    51	// CustomRecoveryWithWriter returns a middleware for a given writer that recovers from any panics and calls the provided handle func to handle it.
    52	func CustomRecoveryWithWriter(out io.Writer, handle RecoveryFunc) HandlerFunc {
    53		var logger *log.Logger
    54		if out != nil {
    55			logger = log.New(out, "\n\n\x1b[31m", log.LstdFlags)
    56		}
    57		return func(c *Context) {
    58			defer func() {
    59				if err := recover(); err != nil {
    60					// Check for a broken connection, as it is not really a
    61					// condition that warrants a panic stack trace.
    62					var brokenPipe bool
    63					if ne, ok := err.(*net.OpError); ok {
    64						var se *os.SyscallError
    65						if errors.As(ne, &se) {
    66							if strings.Contains(strings.ToLower(se.Error()), "broken pipe") || strings.Contains(strings.ToLower(se.Error()), "connection reset by peer") {
    67								brokenPipe = true
    68							}
    69						}
    70					}
    71					if logger != nil {
    72						stack := stack(3)
    73						httpRequest, _ := httputil.DumpRequest(c.Request, false)
    74						headers := strings.Split(string(httpRequest), "\r\n")
    75						for idx, header := range headers {
    76							current := strings.Split(header, ":")
    77							if current[0] == "Authorization" {
    78								headers[idx] = current[0] + ": *"
    79							}
    80						}
    81						headersToStr := strings.Join(headers, "\r\n")
    82						if brokenPipe {
    83							logger.Printf("%s\n%s%s", err, headersToStr, reset)
    84						} else if IsDebugging() {
    85							logger.Printf("[Recovery] %s panic recovered:\n%s\n%s\n%s%s",
    86								timeFormat(time.Now()), headersToStr, err, stack, reset)
    87						} else {
    88							logger.Printf("[Recovery] %s panic recovered:\n%s\n%s%s",
    89								timeFormat(time.Now()), err, stack, reset)
    90						}
    91					}
    92					if brokenPipe {
    93						// If the connection is dead, we can't write a status to it.
    94						c.Error(err.(error)) // nolint: errcheck
    95						c.Abort()
    96					} else {
    97						handle(c, err)
    98					}
    99				}
   100			}()
   101			c.Next()
   102		}
   103	}
