   109	// stack returns a nicely formatted stack frame, skipping skip frames.
   110	func stack(skip int) []byte {
   111		buf := new(bytes.Buffer) // the returned data
   112		// As we loop, we open files and read them. These variables record the currently
   113		// loaded file.
   114		var lines [][]byte
   115		var lastFile string
   116		for i := skip; ; i++ { // Skip the expected number of frames
   117			pc, file, line, ok := runtime.Caller(i)
   118			if !ok {
   119				break
   120			}
   121			// Print this much at least.  If we can't find the source, it won't show.
   122			fmt.Fprintf(buf, "%s:%d (0x%x)\n", file, line, pc)
   123			if file != lastFile {
   124				data, err := ioutil.ReadFile(file)
   125				if err != nil {
   126					continue
   127				}
   128				lines = bytes.Split(data, []byte{'\n'})
   129				lastFile = file
   130			}
   131			fmt.Fprintf(buf, "\t%s: %s\n", function(pc), source(lines, line))
   132		}
   133		return buf.Bytes()
   134	}
