   145	// function returns, if possible, the name of the function containing the PC.
   146	func function(pc uintptr) []byte {
   147		fn := runtime.FuncForPC(pc)
   148		if fn == nil {
   149			return dunno
   150		}
   151		name := []byte(fn.Name())
   152		// The name includes the path name to the package, which is unnecessary
   153		// since the file name is already included.  Plus, it has center dots.
   154		// That is, we see
   155		//	runtime/debug.*T·ptrmethod
   156		// and want
   157		//	*T.ptrmethod
   158		// Also the package path might contain dot (e.g. code.google.com/...),
   159		// so first eliminate the path prefix
   160		if lastSlash := bytes.LastIndex(name, slash); lastSlash >= 0 {
   161			name = name[lastSlash+1:]
   162		}
   163		if period := bytes.Index(name, dot); period >= 0 {
   164			name = name[period+1:]
   165		}
   166		name = bytes.Replace(name, centerDot, dot, -1)
   167		return name
   168	}
